-- Saved standards are immutable history; highest version is effective immediately.
UPDATE standards_versions SET snapshot_json=json_object('standardsVersionId',id,'projectId',project_id,'version',version,'title',title,'requirementSetIds',json(requirement_set_ids_json),'rubricVersionId',rubric_version_id,'mappings',json(mappings_json),'requirements',json((SELECT json_group_array(json_object('requirementId',q.id,'requirementSetId',q.requirement_set_id,'title',q.title,'detail',q.detail,'category',q.category,'dueDate',q.due_date,'duePrecision',q.due_precision,'citations',json(q.citations_json))) FROM (SELECT * FROM requirements WHERE project_id=standards_versions.project_id AND requirement_set_id IN(SELECT value FROM json_each(standards_versions.requirement_set_ids_json)) ORDER BY requirement_set_id,seq) q)),'rubric',json((SELECT json_object('rubricVersionId',r.id,'version',r.version,'weights',json(r.weights_json),'notes',r.notes) FROM rubric_versions r WHERE r.id=standards_versions.rubric_version_id AND r.project_id=standards_versions.project_id))), status='confirmed', confirmed_at=COALESCE(confirmed_at,updated_at) WHERE snapshot_json IS NULL;
UPDATE requirement_sets SET status='confirmed' WHERE id IN(SELECT value FROM standards_versions,json_each(requirement_set_ids_json));
UPDATE requirements SET field_state='confirmed' WHERE requirement_set_id IN(SELECT value FROM standards_versions,json_each(requirement_set_ids_json));
UPDATE rubric_versions SET status='confirmed' WHERE id IN(SELECT rubric_version_id FROM standards_versions);
